fn hash_section<T: Serialize>(section: &T) -> String {
    match serde_json::to_string(section) {
        Ok(json) => {
            let mut hasher = Sha256::new();
            hasher.update(json.as_bytes());
            format!("{:x}", hasher.finalize())
